input.command:
cd /home/user/guidebook && export SCRATCH=/tmp/guidebook-t-027 && mkdir -p $SCRATCH && bash .claude/hooks/ensure-deps.sh >/dev/null 2>&1; python3 -c "import pydantic, jsonschema, yaml" && echo deps ok; sha256sum data/guidebook.db | tee $SCRATCH/db.sha; 
CHECKS="test_run_pipeline_refusals test_db_amend_writers test_scan_contract test_author_presence test_search_log_completeness"
for c in $CHECKS; do cmd=$(python3 -c "import yaml,sys,shlex;print(shlex.join(next(x['cmd'] for x in yaml.safe_load(open('governance/check-registry.yaml'))['checks'] if x['id']==sys.argv[1])))" $c); timeout 900 $cmd > "$SCRATCH/before-$c.txt" 2>&1; echo "$c rc=$? | $(grep -E 'EXAMINED|RESULTS|FAILED|VERDICT' "$SCRATCH/before-$c.txt" | tr '\n' ' ' | cut -c1-200)"; done

